//! Write-path tools: `apply_patch` and `write_file`.
//!
//! These are registered **only** when the CLI is invoked with `--write`.
//! They are scoped to the enclosing git repository via [`SourceTree`]:
//! escapes, git-ignored paths, `.ignore`, and anything under `.git/` are
//! refused. Changes land as local git commits — never pushed. Git is the
//! undo button and the audit trail.

use std::path::Path;
use std::process::Stdio;
use std::sync::Arc;

use rig::tool::{PortableDynamicTool, ToolExecutionError, ToolOutput};
use serde_json::json;
use tokio::io::AsyncWriteExt as _;

use crate::source::SourceTree;
use crate::tool::{map_source_err, scrubbed_env};

/// Paths the agent may never write, relative to the repo root.
fn is_protected(rel: &str) -> bool {
    rel == ".ignore" || rel == ".gitignore" || rel.starts_with(".git/") || rel == ".git"
}

/// Run `git` with `args` in `root`, with the scrubbed environment, capturing
/// output. Returns `Ok((stdout, stderr))` on success, `Err(message)` on
/// failure (the more informative of stdout/stderr, trimmed).
async fn git_run(root: &Path, args: &[&str]) -> Result<(String, String), String> {
    let mut cmd = tokio::process::Command::new("git");
    cmd.current_dir(root);
    cmd.env_clear();
    for (k, v) in scrubbed_env() {
        cmd.env(k, v);
    }
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    cmd.args(args);
    let output = cmd
        .output()
        .await
        .map_err(|e| format!("spawn git {}: {e}", args[0]))?;
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    let stderr = String::from_utf8_lossy(&output.stderr).into_owned();
    if !output.status.success() {
        let msg = if stderr.trim().is_empty() {
            stdout.trim()
        } else {
            stderr.trim()
        };
        return Err(msg.to_string());
    }
    Ok((stdout, stderr))
}

/// Validate a unified diff against the repo (`git apply --check`), then
/// apply it (`git apply`). The diff is fed on stdin; no shell is involved.
async fn git_apply_diff(root: &Path, diff: &str) -> Result<(), String> {
    for check in [true, false] {
        let mut cmd = tokio::process::Command::new("git");
        cmd.current_dir(root);
        cmd.env_clear();
        for (k, v) in scrubbed_env() {
            cmd.env(k, v);
        }
        cmd.stdin(Stdio::piped());
        cmd.stdout(Stdio::piped());
        cmd.stderr(Stdio::piped());
        cmd.arg("apply");
        if check {
            cmd.arg("--check");
        }
        cmd.arg("-");

        let mut child = cmd.spawn().map_err(|e| format!("spawn git apply: {e}"))?;
        let mut stdin = child.stdin.take().ok_or("git apply stdin unavailable")?;
        stdin
            .write_all(diff.as_bytes())
            .await
            .map_err(|e| format!("writing diff to git apply: {e}"))?;
        drop(stdin); // EOF

        let output = child
            .wait_with_output()
            .await
            .map_err(|e| format!("waiting for git apply: {e}"))?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            let stdout = String::from_utf8_lossy(&output.stdout);
            let msg = if stderr.trim().is_empty() {
                stdout.trim()
            } else {
                stderr.trim()
            };
            return Err(format!(
                "git apply {}failed: {msg}",
                if check { "--check " } else { "" }
            ));
        }
    }
    Ok(())
}

/// Reject diffs that touch protected paths (`.ignore`, `.git*`).
fn diff_touches_protected(diff: &str) -> Option<String> {
    for line in diff.lines() {
        for prefix in ["+++ b/", "--- a/"] {
            if let Some(rest) = line.strip_prefix(prefix) {
                let rel = rest.split('\t').next().unwrap_or(rest).trim();
                if is_protected(rel) {
                    return Some(rel.to_string());
                }
            }
        }
    }
    None
}

/// Tool: apply a unified diff to the repository working tree.
pub fn builtin_apply_patch(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
        "apply_patch",
        "Apply a unified diff (git diff format) to the repository working tree. Validates with \
         `git apply --check` first; on failure the git error is returned so the patch can be \
         fixed. If `message` is given, the change is committed with that message. Diffs that \
         touch `.ignore` or `.git*` paths are refused. Changes are local commits only — never \
         pushed.",
        json!({
            "type": "object",
            "properties": {
                "diff": {
                    "type": "string",
                    "description": "Unified diff against the current working tree"
                },
                "message": {
                    "type": "string",
                    "description": "Optional commit message"
                }
            },
            "required": ["diff"]
        }),
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let diff = args
                    .get("diff")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'diff'"))?
                    .to_string();
                let message = args
                    .get("message")
                    .and_then(|v| v.as_str())
                    .filter(|m| !m.trim().is_empty())
                    .map(String::from);

                if let Some(rel) = diff_touches_protected(&diff) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "diff touches protected path: {rel}"
                    )));
                }

                git_apply_diff(tree.root(), &diff)
                    .await
                    .map_err(ToolExecutionError::provider)?;

                let mut out = String::from("patch applied");
                if let Some(msg) = message {
                    // `git apply` only touches the working tree; stage
                    // everything so the commit captures the patch (this also
                    // covers new files and initial commits).
                    git_run(tree.root(), &["add", "-A"])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let note = if stderr.trim().is_empty() {
                        "committed".to_string()
                    } else {
                        format!("committed ({})", stderr.trim())
                    };
                    out.push_str(&format!("\n{note}"));
                }
                Ok(ToolOutput::text(out))
            })
        },
    )
}

/// Tool: write a text file inside the repository.
pub fn builtin_write_file(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
        "write_file",
        "Write a text file inside the git repository. `path` is relative to the repo root. \
         Refused: paths outside the repo, git-ignored paths, `.ignore`, `.gitignore`, anything \
         under `.git/`. If `message` is given, the change is committed with that message. \
         Local commits only — never pushed.",
        json!({
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Path relative to the repo root"
                },
                "content": {
                    "type": "string",
                    "description": "Full file contents"
                },
                "message": {
                    "type": "string",
                    "description": "Optional commit message"
                }
            },
            "required": ["path", "content"]
        }),
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let rel = args
                    .get("path")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'path'"))?
                    .to_string();
                let content = args
                    .get("content")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| {
                        ToolExecutionError::invalid_args("missing string field 'content'")
                    })?
                    .to_string();
                let message = args
                    .get("message")
                    .and_then(|v| v.as_str())
                    .filter(|m| !m.trim().is_empty())
                    .map(String::from);

                if is_protected(&rel) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "path is protected: {rel}"
                    )));
                }

                // Escape/ignore checks via SourceTree (handles `..`, absolute
                // paths, symlink escapes, and ignore rules).
                let abs = tree
                    .resolve_for_write(Path::new(&rel))
                    .map_err(map_source_err)?;
                if tree.is_ignored(&abs) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "path is git-ignored: {}",
                        abs.display()
                    )));
                }

                if let Some(parent) = abs.parent() {
                    std::fs::create_dir_all(parent).map_err(|e| {
                        ToolExecutionError::provider(format!("creating parent dirs: {e}"))
                    })?;
                }
                std::fs::write(&abs, &content).map_err(|e| {
                    ToolExecutionError::provider(format!("writing {}: {e}", abs.display()))
                })?;

                let mut out = format!("wrote {} ({} bytes)", abs.display(), content.len());
                if let Some(msg) = message {
                    git_run(tree.root(), &["add", "--", &rel])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let note = if stderr.trim().is_empty() {
                        "committed".to_string()
                    } else {
                        format!("committed ({})", stderr.trim())
                    };
                    out.push_str(&format!("\n{note}"));
                }
                Ok(ToolOutput::text(out))
            })
        },
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::source::testutil::Fixture;

    #[tokio::test]
    async fn write_file_writes_new_file() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());
        let out = tool
            .execute(serde_json::json!({
                "path": "src/new.rs",
                "content": "pub fn added() {}\n"
            }))
            .await
            .expect("write succeeds");
        let rendered = out.render();
        assert!(rendered.contains("src/new.rs"), "got: {rendered}");
        let written = std::fs::read_to_string(fx.dir.join("src/new.rs")).unwrap();
        assert_eq!(written, "pub fn added() {}\n");
    }

    #[tokio::test]
    async fn write_file_refuses_protected_and_ignored() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());

        let err = tool
            .execute(serde_json::json!({
                "path": ".ignore",
                "content": "junk\n"
            }))
            .await
            .expect_err("protected path must fail");
        assert!(err.to_string().contains("protected"), "got: {err}");

        let err = tool
            .execute(serde_json::json!({
                "path": "target/debug/junk.rs",
                "content": "junk\n"
            }))
            .await
            .expect_err("ignored path must fail");
        assert!(err.to_string().contains("git-ignored"), "got: {err}");
    }

    #[tokio::test]
    async fn write_file_refuses_escapes() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());
        let name = format!("hanihi-write-outside-{}", uuid::Uuid::new_v4());
        let err = tool
            .execute(serde_json::json!({
                "path": format!("../{name}"),
                "content": "x"
            }))
            .await
            .expect_err("escape must fail");
        assert!(err.to_string().contains("escapes"), "got: {err}");
    }

    #[tokio::test]
    async fn apply_patch_applies_and_commits() {
        let fx = Fixture::new();
        // Temp fixture repos have no git identity; make it a real repo and
        // configure one locally.
        git_run(&fx.dir, &["init", "-q"]).await.expect("git init");
        git_run(&fx.dir, &["config", "user.email", "test@hanihi.local"])
            .await
            .expect("config email");
        git_run(&fx.dir, &["config", "user.name", "hanihi-test"])
            .await
            .expect("config name");
        let tool = builtin_apply_patch(fx.tree());
        let diff =
            "--- a/src/main.rs\n+++ b/src/main.rs\n@@ -1 +1,2 @@\n fn main() {}\n+// patched\n";
        let out = tool
            .execute(serde_json::json!({
                "diff": diff,
                "message": "test patch"
            }))
            .await
            .unwrap_or_else(|e| panic!("apply failed: {e}"));
        let rendered = out.render();
        assert!(rendered.contains("patch applied"), "got: {rendered}");
        assert!(rendered.contains("committed"), "got: {rendered}");
        let main = std::fs::read_to_string(fx.dir.join("src/main.rs")).unwrap();
        assert!(main.contains("// patched"));

        // Committed: working tree must be clean.
        let (stdout, _) = git_run(&fx.dir, &["status", "--porcelain"]).await.unwrap();
        assert_eq!(stdout.trim(), "", "expected clean tree, got: {stdout}");
    }

    #[tokio::test]
    async fn apply_patch_rejects_bad_diff_and_protected_paths() {
        let fx = Fixture::new();
        let tool = builtin_apply_patch(fx.tree());

        let err = tool
            .execute(serde_json::json!({ "diff": "not a diff at all" }))
            .await
            .expect_err("bad diff must fail");
        assert!(err.to_string().contains("failed"), "got: {err}");

        let err = tool
            .execute(serde_json::json!({ "diff": "--- a/.ignore\n+++ b/.ignore\n@@ -1 +1 @@\n-x\n+y\n" }))
            .await
            .expect_err("protected diff must fail");
        assert!(err.to_string().contains("protected"), "got: {err}");
    }

    #[test]
    fn protected_path_detection() {
        assert!(is_protected(".ignore"));
        assert!(is_protected(".gitignore"));
        assert!(is_protected(".git/config"));
        assert!(is_protected(".git"));
        assert!(!is_protected("src/main.rs"));
        assert!(!is_protected("docs/.ignore.md"));
    }

    #[test]
    fn diff_protected_scan() {
        assert_eq!(
            diff_touches_protected("--- a/src/main.rs\n+++ b/src/main.rs\n"),
            None
        );
        assert_eq!(
            diff_touches_protected("+++ b/.ignore\n"),
            Some(".ignore".to_string())
        );
        // Path with tab (git diff metadata) is still caught.
        assert_eq!(
            diff_touches_protected("+++ b/.git/config\t2026-01-01\n"),
            Some(".git/config".to_string())
        );
    }
}

//! # hanihi-cli
//!
//! REPL front-end for the agent harness: reedline line editor on top of
//! [`hanihi_core::Agent`]. Supports sessions (`--session` / `--new-session`),
//! one-shot turns (`--once`), and MCP stdio servers.

use std::fs;
use std::path::PathBuf;
use std::sync::Arc;

use clap::Parser;
use hanihi_core::agent::Agent;
use hanihi_core::error::AgentError;
use hanihi_core::session::SessionManager;
use hanihi_core::{
    McpClient, SourceTree, StreamEvent, builtin_apply_patch, builtin_echo, builtin_get_time,
    builtin_grep, builtin_list_dir, builtin_read_file, builtin_read_session_log,
    builtin_run_command, builtin_write_file, connect_chat_model_with_prompt,
};
use reedline::{DefaultPrompt, FileBackedHistory, Reedline, Signal};
use rig::completion::CompletionModel;
use tracing_subscriber::EnvFilter;

const DEFAULT_WORKING_DIR: &str = "./working";
/// Default cap on model turns per request. Effectively unlimited: a sane
/// upper bound so runaway tool-call loops still terminate, but far above any
/// realistic working session.
const DEFAULT_MAX_TURNS: usize = 1000;
/// Default cap on model turns in task mode (long-horizon self-improvement).
const TASK_MAX_TURNS: usize = 1000;

#[derive(Parser, Debug)]
#[command(
    name = "hānihi",
    version,
    about = "Rust agent harness: rig + rmcp + reedline"
)]
struct Args {
    /// OpenAI-compatible chat completions base URL.
    #[arg(
        long,
        env = "LLM_BASE_URL",
        default_value = "https://api.deepseek.com/v1"
    )]
    base_url: String,

    /// API key (or set LLM_API_KEY).
    #[arg(long, env = "LLM_API_KEY")]
    api_key: Option<String>,

    /// Model name (or set LLM_MODEL).
    #[arg(long, env = "LLM_MODEL", default_value = "deepseek-chat")]
    model: String,

    /// Working directory for sessions (default: ./working, relative to cwd).
    #[arg(long, env = "HANIHI_WORKING_DIR", default_value = DEFAULT_WORKING_DIR)]
    working_dir: PathBuf,

    /// Use an existing session by name (default: "default-session").
    #[arg(long, default_value = "default-session")]
    session: String,

    /// Create a new session with this name and use it.
    #[arg(long, conflicts_with = "session")]
    new_session: Option<String>,

    /// MCP stdio server command(s) to attach, e.g.
    /// `--mcp-command "./target/debug/mcp-echo-server"`. May be repeated.
    #[arg(long = "mcp-command", value_name = "CMD")]
    mcp_commands: Vec<String>,

    /// Run a single turn and exit (no REPL).
    #[arg(long, value_name = "PROMPT")]
    once: Option<String>,

    /// Register write tools (apply_patch, write_file) — enables editing the
    /// enclosing repository. Off by default; analysis and build tools are
    /// always on.
    #[arg(long)]
    write: bool,

    /// Run a single long-horizon turn with the task-mode system prompt
    /// (workflow gates: fmt → test → build → clippy → commit). Takes
    /// precedence over --once.
    #[arg(long, value_name = "PROMPT")]
    task: Option<String>,

    /// Maximum model turns per request (default: 1000; task mode: 1000).
    #[arg(long)]
    max_turns: Option<usize>,

    /// Append this text to the system prompt. Repeatable. When used with an
    /// existing session, the appended text is persisted to the session so it
    /// applies on future resumes too.
    #[arg(long = "prompt", value_name = "TEXT")]
    prompt_append: Vec<String>,

    /// Append the content of this file to the system prompt. Repeatable.
    /// When used with an existing session, the appended content is persisted
    /// to the session so it applies on future resumes too.
    #[arg(long = "prompt-file", value_name = "PATH")]
    prompt_files: Vec<PathBuf>,

    /// Replace the entire system prompt with the additions (no base prompt
    /// is prepended). For use with --session to rewrite the stored prompt,
    /// or with --new-session to override the default. Mutually exclusive
    /// with --prompt/--prompt-file append semantics (see below).
    #[arg(long)]
    new_prompt: bool,
}

/// Extract a short provider name from a base URL hostname.
fn provider_from_url(url: &str) -> &str {
    // Strip scheme.
    let host = url
        .trim_start_matches("https://")
        .trim_start_matches("http://")
        .split('/')
        .next()
        .unwrap_or("unknown");
    // e.g. "api.deepseek.com" -> "deepseek", "api.openai.com" -> "openai"
    host.trim_start_matches("api.")
        .trim_start_matches("api-")
        .split('.')
        .next()
        .unwrap_or("unknown")
}

/// Read the given prompt files and return their concatenated contents.
fn read_prompt_files(paths: &[PathBuf]) -> Result<String, AgentError> {
    let mut out = String::new();
    for path in paths {
        let content = fs::read_to_string(path)?;
        if !out.is_empty() {
            out.push('\n');
        }
        out.push_str(&content);
    }
    Ok(out)
}

/// Concatenate the explicit additions (`--prompt` strings and the contents
/// of `--prompt-file` files) into one block.
fn collect_extras(
    prompt_appends: &[String],
    prompt_files: &[PathBuf],
) -> Result<String, AgentError> {
    let file_text = read_prompt_files(prompt_files)?;
    let mut parts: Vec<String> = Vec::new();
    parts.extend(prompt_appends.iter().cloned());
    if !file_text.is_empty() {
        parts.push(file_text);
    }
    Ok(parts.join("\n\n"))
}

/// Whether any explicit prompt additions were supplied.
fn has_extras(prompt_appends: &[String], prompt_files: &[PathBuf]) -> bool {
    !prompt_appends.is_empty() || !prompt_files.is_empty()
}

/// Read the system prompt stored in an existing session's session.json.
fn stored_session_prompt(working_dir: &std::path::Path, session_name: &str) -> Option<String> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read_to_string(meta_path).ok()?;
    let meta: serde_json::Value = serde_json::from_str(&bytes).ok()?;
    meta.get("system_prompt")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

/// Persist a system prompt into an existing session's session.json. Reads
/// the file, updates the field, writes it back.
fn write_session_prompt(
    working_dir: &std::path::Path,
    session_name: &str,
    prompt: &str,
) -> Result<(), AgentError> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read(&meta_path).map_err(AgentError::Io)?;
    let mut meta: serde_json::Value = serde_json::from_slice(&bytes).map_err(AgentError::Json)?;
    meta["system_prompt"] = serde_json::Value::String(prompt.to_string());
    fs::write(&meta_path, serde_json::to_string_pretty(&meta)?).map_err(AgentError::Io)?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), AgentError> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let args = Args::parse();
    let api_key = args
        .api_key
        .filter(|k| !k.is_empty())
        .ok_or(AgentError::MissingApiKey)?;

    // Resolve working directory relative to cwd.
    let working_dir = if args.working_dir.is_absolute() {
        args.working_dir.clone()
    } else {
        std::env::current_dir()?.join(&args.working_dir)
    };

    let mut mgr = SessionManager::new(&working_dir);
    let provider = provider_from_url(&args.base_url);

    let task_mode = args.task.is_some();
    let base_prompt: &str = if task_mode {
        hanihi_core::agent::TASK_SYSTEM_PROMPT
    } else {
        hanihi_core::agent::DEFAULT_SYSTEM_PROMPT
    };

    // Determine session name and whether to auto-create.
    let (session_name, is_new) = if let Some(ref name) = args.new_session {
        (name.clone(), true)
    } else {
        let name = args.session.clone();
        // Auto-create default-session if it doesn't exist.
        let is_new = name == "default-session" && !mgr.exists(&name);
        (name, is_new)
    };

    let had_extras = has_extras(&args.prompt_append, &args.prompt_files);

    // Resolve the system prompt this invocation will use, and whether it
    // must be persisted back to the session's metadata.
    //
    // Prompt resolution rules:
    //  - `--new-prompt` on any session: the additions (collected from
    //    --prompt / --prompt-file) become the ENTIRE prompt. On an existing
    //    session this replaces and persists the stored prompt.
    //  - Otherwise `--prompt` / `--prompt-file` append to the base prompt
    //    (new session) or to the stored prompt (existing session), and the
    //    appended result is persisted so it survives a resume.
    //  - With no additions at all, the existing stored prompt is used
    //    unchanged (or the base prompt for a fresh session).
    let (session_prompt, do_persist) = if args.new_prompt {
        // Replace/set the entire prompt from the additions only.
        let prompt = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let effective = if prompt.trim().is_empty() {
            // --new-prompt with nothing supplied: use base as the new prompt.
            base_prompt.to_string()
        } else {
            prompt
        };
        if is_new {
            (effective, false) // creation persists it
        } else {
            (effective, true) // replace + persist the stored prompt
        }
    } else if is_new {
        // Fresh session: base + any appends. persisted by creation.
        let prompt = if had_extras {
            let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
            format!("{base_prompt}\n\n{extras}")
        } else {
            base_prompt.to_string()
        };
        (prompt, false)
    } else if had_extras {
        // Existing session with appends: stored + extras, persisted.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let prompt = format!("{stored}\n\n{extras}");
        (prompt, true)
    } else {
        // Existing session, no additions: use stored prompt unchanged.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        (stored, false)
    };

    // Create or open the session.
    if is_new {
        if session_name == "default-session" {
            mgr.create_default(&args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("auto-created session 'default-session'");
        } else {
            mgr.create(&session_name, &args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("created session '{session_name}'");
        }
    } else {
        mgr.open(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        if do_persist {
            write_session_prompt(&working_dir, &session_name, &session_prompt)?;
            if args.new_prompt {
                println!("session '{session_name}' system prompt replaced");
            } else {
                println!("session '{session_name}' system prompt extended");
            }
        }
    }

    // Build the agent with the resolved system prompt.
    let mut agent = connect_chat_model_with_prompt(
        args.base_url.clone(),
        api_key.clone(),
        args.model.clone(),
        &session_prompt,
    )?;
    agent.set_max_turns(args.max_turns.unwrap_or(if task_mode {
        TASK_MAX_TURNS
    } else {
        DEFAULT_MAX_TURNS
    }));
    agent.add_tool(builtin_get_time());
    agent.add_tool(builtin_echo());

    // Source-tree tools: read/list/grep/run-command over the enclosing git
    // repository, plus a window into this session's own event log. Ignore
    // rules (.gitignore, .ignore) filter what the agent can see. Write tools
    // (apply_patch, write_file) are registered only with --write.
    match SourceTree::open() {
        Ok(tree) => {
            let tree = Arc::new(tree);
            let traces_dir = working_dir.join("traces").join(&session_name);
            let log_path = working_dir
                .join("sessions")
                .join(&session_name)
                .join("events.jsonl");
            agent.add_tool(builtin_read_file(tree.clone()));
            agent.add_tool(builtin_list_dir(tree.clone()));
            agent.add_tool(builtin_grep(tree.clone()));
            agent.add_tool(builtin_run_command(tree.clone(), traces_dir));
            agent.add_tool(builtin_read_session_log(log_path));
            if args.write {
                agent.add_tool(builtin_apply_patch(tree.clone()));
                agent.add_tool(builtin_write_file(tree));
            }
        }
        Err(e) => println!("source tools disabled (no git repository): {e}"),
    }

    for command in &args.mcp_commands {
        let parts: Vec<String> = command.split_whitespace().map(String::from).collect();
        let (program, rest) = parts.split_first().ok_or_else(|| AgentError::Tool {
            name: "<mcp>".into(),
            message: "empty --mcp-command".into(),
        })?;
        let client = McpClient::connect_stdio(program, rest).await?;
        let tools = client.tool_defs().await?;
        let count = tools.len();
        for tool in tools {
            agent.add_tool(tool);
        }
        println!("attached MCP server '{program}': {count} tool(s)");
    }

    // Get a mutable reference to the open session so we can read its turn
    // count for the "session renewed" metadata below.
    let session = mgr
        .open(&session_name)
        .map_err(|_e| AgentError::Rig("failed to re-open session".into()))?;

    // Replay prior turns from the event log so the agent remembers
    // previous conversations in this session.
    let mut prior_turns = None;
    match session.replay_history() {
        Ok(history) if !history.is_empty() => {
            let msg_count = history.len();
            agent.set_history(history);
            println!("replayed {msg_count} messages from prior session");
        }
        Ok(_) => {} // empty history, nothing to replay
        Err(e) => {
            tracing::warn!("failed to replay session history: {e}");
        }
    }
    // How many turns has this session accumulated so far (including from
    // prior sessions)? Use the session's own counter; it is monotonically
    // increasing across restarts of the same session name.
    if let Ok(turns) = session.total_turns() {
        prior_turns = Some(turns);
    }

    println!(
        "agent ready: model={} tools={} session='{session_name}' max_turns={}{}",
        args.model,
        agent.tool_count(),
        agent.max_turns(),
        if args.write {
            " (write tools enabled)"
        } else {
            ""
        },
    );
    if let Some(t) = prior_turns {
        println!(
            "session '{}' renewed: total turns so far = {t}",
            session_name
        );
    }
    println!("system prompt: {} bytes", session_prompt.len());

    let prompt = args.task.clone().or_else(|| args.once.clone());
    if let Some(prompt) = prompt {
        let mut rx = session
            .run_streaming(&mut agent, provider, &args.model, &prompt)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        while let Some(event) = rx.recv().await {
            match event {
                StreamEvent::TextDelta { text } => print!("{text}"),
                StreamEvent::ToolCallStart { name, .. } => print!("\n[🔧 {name}"),
                StreamEvent::ToolCallArgs { .. } => {}
                StreamEvent::ToolCallReady { .. } => {}
                StreamEvent::ToolResult { .. } => println!(" ✅]"),
                StreamEvent::TurnComplete { summary } => {
                    println!();
                    println!(
                        "[turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                        session.turn,
                        summary.tool_calls,
                        summary.usage.input_tokens,
                        summary.usage.output_tokens,
                        agent.max_turns()
                    );
                    agent.set_history(summary.final_history);
                    break;
                }
                StreamEvent::Error { message } => {
                    eprintln!();
                    eprintln!("error: {message}");
                    break;
                }
            }
        }
        mgr.close(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        return Ok(());
    }

    repl(session, agent, provider, &args.model).await?;

    mgr.close(&session_name)
        .map_err(|e| AgentError::Rig(e.to_string()))?;
    Ok(())
}

/// Interactive readline loop.
async fn repl<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    mut agent: Agent<M>,
    provider: &str,
    model_name: &str,
) -> Result<(), AgentError> {
    let history_path = session.root().join("history.txt");
    let history: Box<dyn reedline::History> =
        match FileBackedHistory::with_file(10_000, history_path) {
            Ok(h) => Box::new(h),
            Err(e) => {
                eprintln!("history file disabled: {e}");
                Box::new(FileBackedHistory::new(10_000).expect("in-memory history"))
            }
        };
    let mut editor = Reedline::create().with_history(history);
    let prompt = DefaultPrompt::default();

    loop {
        match editor.read_line(&prompt) {
            Ok(Signal::Success(line) | Signal::HostCommand(line)) => {
                let line = line.trim().to_string();
                match line.as_str() {
                    "" => continue,
                    "/quit" | "/exit" => break,
                    "/help" => {
                        println!(
                            "commands: /help /tools /clear /session /quit — anything else is sent to the model"
                        );
                        continue;
                    }
                    "/tools" => {
                        for def in agent.tool_definitions() {
                            println!("- {}: {}", def.name, def.description);
                        }
                        continue;
                    }
                    "/clear" => {
                        agent.clear_history();
                        println!("history cleared");
                        continue;
                    }
                    "/session" => {
                        println!(
                            "session: '{}' (id={}) turn={} max_turns={}",
                            session.name,
                            session.id,
                            session.turn,
                            agent.max_turns()
                        );
                        continue;
                    }
                    _ => {}
                }
                match session
                    .run_streaming(&mut agent, provider, model_name, &line)
                    .await
                {
                    Ok(mut rx) => {
                        while let Some(event) = rx.recv().await {
                            match event {
                                StreamEvent::TextDelta { text } => print!("{text}"),
                                StreamEvent::ToolCallStart { name, .. } => {
                                    print!("\n[🔧 {name}")
                                }
                                StreamEvent::ToolCallArgs { .. } => {}
                                StreamEvent::ToolCallReady { .. } => {}
                                StreamEvent::ToolResult { .. } => println!(" ✅]"),
                                StreamEvent::TurnComplete { summary } => {
                                    println!();
                                    println!(
                                        "[turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                                        session.turn,
                                        summary.tool_calls,
                                        summary.usage.input_tokens,
                                        summary.usage.output_tokens,
                                        agent.max_turns()
                                    );
                                    agent.set_history(summary.final_history);
                                    break;
                                }
                                StreamEvent::Error { message } => {
                                    eprintln!();
                                    eprintln!("error: {message}");
                                    break;
                                }
                            }
                        }
                    }
                    Err(e) => eprintln!("error: {e}"),
                }
            }
            Ok(Signal::CtrlC) | Ok(Signal::ExternalBreak(_)) => continue,
            Ok(Signal::CtrlD) => break,
            Ok(_) => continue,
            Err(e) => {
                eprintln!("readline error: {e}");
                break;
            }
        }
    }

    // Sync history to disk before shutting down.
    if let Err(e) = editor.sync_history() {
        eprintln!("warning: failed to sync history: {e}");
    }
    Ok(())
}

//! Built-in tools for the agent.
//!
//! Tools are rig [`PortableDynamicTool`]s: name + description + JSON schema +
//! an async callback taking raw `serde_json::Value` arguments.

use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use chrono::Utc;
use grep_regex::{RegexMatcher, RegexMatcherBuilder};
use grep_searcher::{Searcher, Sink, SinkMatch};
use rig::tool::{PortableDynamicTool, ToolExecutionError, ToolOutput};
use serde_json::json;
use tokio::io::AsyncReadExt as _;

use crate::source::{SourceError, SourceTree};

/// Map a [`SourceError`] onto a rig tool error with the right kind.
pub(crate) fn map_source_err(e: SourceError) -> ToolExecutionError {
    match e {
	SourceError::NotFound(p) => {
	    ToolExecutionError::not_found(format!("no such path: {}", p.display()))
	}
	SourceError::Ignored(p) => {
	    ToolExecutionError::permission_denied(format!("path is git-ignored: {}", p.display()))
	}
	SourceError::Escape(p) => ToolExecutionError::permission_denied(format!(
	    "path escapes the repository: {}",
	    p.display()
	)),
	other => ToolExecutionError::provider(other.to_string()),
    }
}

/// Tool: report the current local date and time.
pub fn builtin_get_time() -> PortableDynamicTool {
    PortableDynamicTool::new(
	"get_time",
	"Get the current local date and time in RFC 3339 format.",
	json!({
	    "type": "object",
	    "properties": {}
	}),
	|_args: serde_json::Value| {
	    Box::pin(async move {
		let now = chrono::Local::now().to_rfc3339();
		Ok(ToolOutput::text(now))
	    })
	},
    )
}

/// Tool: echo the provided text back verbatim.
pub fn builtin_echo() -> PortableDynamicTool {
    PortableDynamicTool::new(
	"echo",
	"Echo the provided text back verbatim.",
	json!({
	    "type": "object",
	    "properties": {
	    "text": { "type": "string", "description": "Text to echo" }
	    },
	    "required": ["text"]
	}),
	|args: serde_json::Value| {
	    Box::pin(async move {
		let text = args
		    .get("text")
		    .and_then(|v| v.as_str())
		    .unwrap_or_default()
		    .to_string();
		Ok(ToolOutput::text(text))
	    })
	},
    )
}

/// Tool: read a text file from the git repository.
pub fn builtin_read_file(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"read_file",
	"Read a text file from the git repository. `path` is relative to the repo root. \
	 Git-ignored paths cannot be read. Returns up to 64 KiB.",
	json!({
	    "type": "object",
	    "properties": {
	    "path": { "type": "string", "description": "Path relative to the repo root" }
	    },
	    "required": ["path"]
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    Box::pin(async move {
		let rel = args.get("path").and_then(|v| v.as_str()).ok_or_else(|| {
		    ToolExecutionError::invalid_args("missing string field 'path'")
		})?;
		tree.read(Path::new(rel))
		    .map(ToolOutput::text)
		    .map_err(map_source_err)
	    })
	},
    )
}

/// Tool: list files and directories in the git repository.
pub fn builtin_list_dir(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"list_dir",
	"List files and directories in the git repository. `path` is relative to the repo root \
	 (default: the root itself). `depth` controls recursion (default 1, max 4). \
	 Git-ignored paths are never listed. One line per entry: type + path.",
	json!({
	    "type": "object",
	    "properties": {
	    "path": { "type": "string", "description": "Directory relative to repo root" },
	    "depth": { "type": "integer", "description": "Recursion depth (1-4)" }
	    }
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    Box::pin(async move {
		let rel = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
		let depth = args
		    .get("depth")
		    .and_then(|v| v.as_u64())
		    .unwrap_or(1)
		    .clamp(1, 4) as usize;
		let walk = tree.walk(Path::new(rel), depth).map_err(map_source_err)?;
		let mut lines = Vec::new();
		for entry in walk {
		    let entry = entry.map_err(|e| ToolExecutionError::provider(e.to_string()))?;
		    if entry.depth() == 0 {
			continue;
		    }
		    let ty = match entry.file_type() {
			Some(t) if t.is_dir() => "dir ",
			Some(t) if t.is_file() => "file",
			Some(t) if t.is_symlink() => "link",
			_ => "oth ",
		    };
		    let p = entry
			.path()
			.strip_prefix(tree.root())
			.unwrap_or(entry.path());
		    lines.push(format!("{ty} {}", p.display()));
		}
		Ok(ToolOutput::text(lines.join("\n")))
	    })
	},
    )
}

// ── run_command ──────────────────────────────────────────────────

/// Default timeout for `run_command`.
const DEFAULT_TIMEOUT_SECS: u64 = 120;
/// Maximum allowed timeout for `run_command`.
const MAX_TIMEOUT_SECS: u64 = 600;

/// Per-process sequence number for trace filenames. The tool cannot see the
/// session turn number, so unix-ms + a per-process counter disambiguates
/// traces within a session directory.
static TRACE_SEQ: AtomicU64 = AtomicU64::new(0);

/// Result of executing a command (spawn, wait, capture, timeout).
struct CommandOutcome {
    exit_code: Option<i32>,
    timed_out: bool,
    duration_ms: u64,
    stdout: String,
    stderr: String,
}

/// Validate a whitespace-split command against the allowlist.
///
/// `argv[0]` must be `cargo` or `git`. Cargo subcommands are limited to
/// `check`, `build`, `test`, `clippy`, `fmt`, `doc`, and `run -p hanihi-eval`.
/// Git is limited to the read-only verbs `status`, `diff`, `log`, `show`, and
/// `apply --check`. Flags that would change the working directory
/// (`--manifest-path`, `-C`/`--directory`) are rejected outright — the cwd is
/// pinned to the repo root and nothing may escape it.
fn check_command_argv(argv: &[String]) -> Result<(), String> {
    let Some(program) = argv.first() else {
	return Err("empty command".into());
    };
    match program.as_str() {
	"cargo" => {
	    let Some(sub) = argv.get(1) else {
		return Err(
		    "cargo requires a subcommand (check, build, test, clippy, fmt, doc, run)"
			.into(),
		);
	    };
	    if argv.iter().any(|a| a == "--manifest-path") {
		return Err(
		    "cargo --manifest-path is not allowed (cwd is pinned to the repo root)".into(),
		);
	    }
	    match sub.as_str() {
		"check" | "build" | "test" | "clippy" | "fmt" | "doc" => Ok(()),
		"run" => {
		    // Only `cargo run -p hanihi-eval` is permitted.
		    let mut package: Option<&str> = None;
		    let mut iter = argv[1..].iter().peekable();
		    while let Some(a) = iter.next() {
			if a == "--" {
			    break;
			}
			if a == "-p" || a == "--package" {
			    package = iter.peek().map(|s| s.as_str());
			}
		    }
		    match package {
			Some("hanihi-eval") => Ok(()),
			Some(other) => Err(format!(
			    "cargo run is restricted to -p hanihi-eval (got -p {other})"
			)),
			None => Err("cargo run requires -p hanihi-eval".into()),
		    }
		}
		other => Err(format!("cargo subcommand '{other}' is not allowed")),
	    }
	}
	"git" => {
	    let Some(sub) = argv.get(1) else {
		return Err("git requires a subcommand (status, diff, log, show, apply)".into());
	    };
	    if argv.iter().any(|a| a == "-C" || a == "--directory") {
		return Err(
		    "git -C/--directory is not allowed (cwd is pinned to the repo root)".into(),
		);
	    }
	    match sub.as_str() {
		"status" | "diff" |  "log" | "show" => Ok(()),
		"apply" => {
		    if !argv.iter().any(|a| a == "--check") {
			return Err("git apply is restricted to --check".into());
		    }
		    Ok(())
		}
		other => Err(format!("git subcommand '{other}' is not allowed")),
	    }
	}
	other => Err(format!(
	    "command '{other}' is not allowed (only cargo and git)"
	)),
    }
}

/// Build the minimal environment passed to child processes: PATH, HOME, and
/// CARGO_* / RUSTUP_* (needed for cargo/rustup to resolve the toolchain).
/// Everything else (API keys, etc.) is dropped.
pub(crate) fn scrubbed_env() -> Vec<(String, String)> {
    std::env::vars()
	.filter(|(k, _)| {
	    k == "PATH" || k == "HOME" || k.starts_with("CARGO_") || k.starts_with("RUSTUP_")
	})
	.collect()
}

/// Read a pipe to EOF as a lossy UTF-8 string.
async fn read_all<R>(mut reader: R) -> std::io::Result<String>
where
    R: tokio::io::AsyncRead + Unpin,
{
    let mut buf = Vec::new();
    reader.read_to_end(&mut buf).await?;
    Ok(String::from_utf8_lossy(&buf).into_owned())
}

/// Cap a string at `MAX_READ_BYTES`, appending a truncation note.
fn cap_output(s: &str) -> String {
    if s.len() <= crate::source::MAX_READ_BYTES {
	s.to_string()
    } else {
	let cut = s.floor_char_boundary(crate::source::MAX_READ_BYTES);
	let mut out = String::with_capacity(cut + 64);
	out.push_str(&s[..cut]);
	out.push_str(&format!("\n…[truncated, {} bytes total]", s.len()));
	out
    }
}

/// Spawn `argv`, capture stdout/stderr, enforce a timeout (killing the child
/// on expiry), and return the outcome. The allowlist check happens in the
/// tool wrapper; this runs whatever argv it is given (used directly by tests).
async fn execute_captured(
    argv: &[String],
    cwd: &Path,
    timeout: Duration,
) -> Result<CommandOutcome, String> {
    let mut cmd = tokio::process::Command::new(&argv[0]);
    cmd.args(&argv[1..]);
    cmd.current_dir(cwd);
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    cmd.env_clear();
    for (k, v) in scrubbed_env() {
	cmd.env(k, v);
    }

    let mut child = cmd
	.spawn()
	.map_err(|e| format!("failed to spawn '{}': {e}", argv[0]))?;
    let stdout_pipe = child.stdout.take().expect("piped stdout");
    let stderr_pipe = child.stderr.take().expect("piped stderr");

    // Read both pipes concurrently with the wait so a large stream on one
    // pipe cannot deadlock the other.
    let stdout_task = tokio::spawn(read_all(stdout_pipe));
    let stderr_task = tokio::spawn(read_all(stderr_pipe));

    let started = Instant::now();
    let status_result = tokio::time::timeout(timeout, child.wait()).await;

    let (exit_code, timed_out) = match status_result {
	Ok(Ok(status)) => (status.code(), false),
	Ok(Err(e)) => return Err(format!("waiting for '{}': {e}", argv[0])),
	Err(_elapsed) => {
	    // Kill the child on expiry; the readers hit EOF and complete.
	    let _ = child.kill().await;
	    let _ = child.wait().await;
	    (None, true)
	}
    };

    let stdout = stdout_task
	.await
	.map_err(|e| format!("stdout task failed: {e}"))?
	.map_err(|e| format!("reading stdout: {e}"))?;
    let stderr = stderr_task
	.await
	.map_err(|e| format!("stderr task failed: {e}"))?
	.map_err(|e| format!("reading stderr: {e}"))?;

    Ok(CommandOutcome {
	exit_code,
	timed_out,
	duration_ms: started.elapsed().as_millis() as u64,
	stdout,
	stderr,
    })
}

/// Persist a command execution to `<traces-dir>/<unix-ms>-<seq>.cmd.json`.
fn write_trace(
    traces_dir: &Path,
    command: &str,
    outcome: &CommandOutcome,
) -> std::io::Result<PathBuf> {
    std::fs::create_dir_all(traces_dir)?;
    let seq = TRACE_SEQ.fetch_add(1, Ordering::Relaxed);
    let ms = Utc::now().timestamp_millis();
    let name = format!("{ms}-{seq}.cmd.json");
    let path = traces_dir.join(name);
    let obj = json!({
    "ts": Utc::now().to_rfc3339(),
    "command": command,
    "exit_code": outcome.exit_code,
    "duration_ms": outcome.duration_ms,
    "stdout": outcome.stdout,
    "stderr": outcome.stderr,
    });
    std::fs::write(&path, serde_json::to_string_pretty(&obj)?)?;
    Ok(path)
}

/// Render the tool result: exit code + duration + truncated output + trace path.
fn render_command_result(command: &str, outcome: &CommandOutcome, trace_path: &Path) -> String {
    let code = match outcome.exit_code {
	Some(c) => c.to_string(),
	None if outcome.timed_out => "killed (timeout)".to_string(),
	None => "killed (signal)".to_string(),
    };
    let mut out = format!(
	"command: {command}\nexit code: {code}\nduration: {}ms\n",
	outcome.duration_ms
    );
    if !outcome.stdout.is_empty() {
	out.push_str("--- stdout ---\n");
	out.push_str(&cap_output(&outcome.stdout));
	out.push('\n');
    }
    if !outcome.stderr.is_empty() {
	out.push_str("--- stderr ---\n");
	out.push_str(&cap_output(&outcome.stderr));
	out.push('\n');
    }
    out.push_str(&format!("trace: {}", trace_path.display()));
    out
}

/// Tool: run an allowlisted `cargo`/`git` command inside the repo root.
///
/// Registered always (it is an analysis/build tool, not a write tool). The
/// command is split on whitespace (no shell), validated against an allowlist,
/// executed with a scrubbed environment and a timeout, and the full output is
/// persisted to a trace file. The result carries exit code + duration +
/// truncated stdout/stderr + the trace path.
pub fn builtin_run_command(tree: Arc<SourceTree>, traces_dir: PathBuf) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"run_command",
	"Run an allowlisted command inside the repository root. No shell: the command is \
	 split on whitespace into argv. cargo subcommands: check, build, test, clippy, fmt, \
	 doc, run -p hanihi-eval. git subcommands: status, diff, log, show, apply --check. \
	 cwd is pinned to the repo root; the environment is scrubbed (PATH, HOME, CARGO_* \
	 only); output is capped at 64 KiB; the full output is written to a trace file. \
	 Returns exit code, duration, stdout/stderr (truncated), and the trace path.",
	json!({
	    "type": "object",
	    "properties": {
	    "command": {
		"type": "string",
		"description": "Allowlisted command, e.g. \"cargo check --workspace\""
	    },
	    "timeout_secs": {
		"type": "integer",
		"description": "Max seconds (default 120, max 600)"
	    }
	    },
	    "required": ["command"]
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    let traces_dir = traces_dir.clone();
	    Box::pin(async move {
		let command = args
		    .get("command")
		    .and_then(|v| v.as_str())
		    .ok_or_else(|| {
			ToolExecutionError::invalid_args("missing string field 'command'")
		    })?
		    .to_string();
		let timeout_secs = args
		    .get("timeout_secs")
		    .and_then(|v| v.as_u64())
		    .unwrap_or(DEFAULT_TIMEOUT_SECS)
		    .clamp(1, MAX_TIMEOUT_SECS);

		let argv: Vec<String> = command.split_whitespace().map(String::from).collect();
		if argv.is_empty() {
		    return Err(ToolExecutionError::invalid_args("empty command"));
		}
		check_command_argv(&argv).map_err(ToolExecutionError::permission_denied)?;

		let outcome =
		    execute_captured(&argv, tree.root(), Duration::from_secs(timeout_secs))
			.await
			.map_err(ToolExecutionError::provider)?;
		let trace_path = write_trace(&traces_dir, &command, &outcome)
		    .map_err(|e| ToolExecutionError::provider(format!("writing trace: {e}")))?;
		Ok(ToolOutput::text(render_command_result(
		    &command,
		    &outcome,
		    &trace_path,
		)))
	    })
	},
    )
}

/// Maximum number of matches `grep` returns before truncating.
const MAX_GREP_MATCHES: usize = 200;
/// Maximum total bytes of `grep` output before truncating.
const MAX_GREP_BYTES: usize = 64 * 1024;

/// Collects `path:line: text` matches for [`builtin_grep`], capped at
/// [`MAX_GREP_MATCHES`] matches / [`MAX_GREP_BYTES`] bytes.
///
/// `grep-searcher`'s `SinkMatch` carries no path, so the caller sets
/// [`MatchSink::current_path`] before each single-file search.
struct MatchSink {
    current_path: PathBuf,
    lines: Vec<String>,
    bytes: usize,
    capped: bool,
}

impl Sink for MatchSink {
    type Error = Box<dyn std::error::Error>;

    fn matched(
	&mut self,
	_searcher: &Searcher,
	lines: &SinkMatch<'_>,
    ) -> Result<bool, Self::Error> {
	let path = self.current_path.display();
	let line_no = lines.line_number().unwrap_or(0);
	let text = String::from_utf8_lossy(lines.bytes());
	let entry = format!("{path}:{line_no}: {}", text.trim_end());
	self.bytes += entry.len();
	self.lines.push(entry);
	if self.lines.len() >= MAX_GREP_MATCHES || self.bytes >= MAX_GREP_BYTES {
	    self.capped = true;
	    return Ok(false);
	}
	Ok(true)
    }
}

/// Tool: regex-search file contents inside the git repository.
///
/// Walks the repo honouring ignore rules (via [`SourceTree::walk`]) and
/// searches each file with ripgrep's searcher. Results are
/// `path:line: text` entries capped at [`MAX_GREP_MATCHES`] matches /
/// [`MAX_GREP_BYTES`] bytes. Binary files are skipped.
pub fn builtin_grep(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"grep",
	"Search file contents in the git repository with a regular expression. `pattern` is a \
	 regex (ripgrep syntax). `path` is a directory relative to the repo root (default: the \
	 root). `ignore_case` makes the match case-insensitive. Git-ignored paths are never \
	 searched. Results are `path:line: text` entries, capped at 200 matches.",
	json!({
	    "type": "object",
	    "properties": {
	    "pattern": { "type": "string", "description": "Regular expression to search for" },
	    "path": { "type": "string", "description": "Directory relative to repo root (default: root)" },
	    "ignore_case": { "type": "boolean", "description": "Case-insensitive match" }
	    },
	    "required": ["pattern"]
	}),
	move |args: serde_json::Value| {
	    let tree = tree.clone();
	    Box::pin(async move {
		let pattern = args
		    .get("pattern")
		    .and_then(|v| v.as_str())
		    .ok_or_else(|| {
			ToolExecutionError::invalid_args("missing string field 'pattern'")
		    })?;
		let rel = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
		let ignore_case = args
		    .get("ignore_case")
		    .and_then(|v| v.as_bool())
		    .unwrap_or(false);

		let matcher = if ignore_case {
		    RegexMatcherBuilder::new()
			.case_insensitive(true)
			.build(pattern)
		} else {
		    RegexMatcher::new(pattern)
		}
		.map_err(|e| ToolExecutionError::invalid_args(format!("invalid regex: {e}")))?;

		let mut sink = MatchSink {
		    current_path: PathBuf::new(),
		    lines: Vec::new(),
		    bytes: 0,
		    capped: false,
		};
		let mut searcher = Searcher::new();
		searcher.set_binary_detection(grep_searcher::BinaryDetection::quit(b'\x00'));

		let walk = tree
		    .walk(Path::new(rel), usize::MAX)
		    .map_err(map_source_err)?;
		for entry in walk {
		    let entry = entry.map_err(|e| ToolExecutionError::provider(e.to_string()))?;
		    if !entry.file_type().map(|t| t.is_file()).unwrap_or(false) {
			continue;
		    }
		    let path = entry.path();
		    sink.current_path = path.to_path_buf();
		    searcher
			.search_path(matcher.clone(), path, &mut sink)
			.map_err(|e| {
			    ToolExecutionError::provider(format!(
				"searching {}: {e}",
				path.display()
			    ))
			})?;
		    if sink.capped {
			break;
		    }
		}

		let mut out = if sink.lines.is_empty() {
		    "no matches".to_string()
		} else {
		    sink.lines.join("\n")
		};
		if sink.capped {
		    out.push_str("\n…[truncated: too many matches]");
		}
		Ok(ToolOutput::text(out))
	    })
	},
    )
}

/// Tool: read entries from this session's event log (the agent's own trace).
///
/// The log lives outside the repo (under the working dir), so the source-tree
/// tools cannot see it. This tool gives the agent a window into its own past
/// executions — the raw material for studying traces of execution.
pub fn builtin_read_session_log(log_path: PathBuf) -> PortableDynamicTool {
    PortableDynamicTool::new(
	"read_session_log",
	"Read entries from this session's event log. `kind` filters by event kind \
	 (user_input, llm_prompt, llm_response, tool_execution, turn_complete, error, \
	 session_created, ...). `turn` filters by turn number. `tail` returns only the last N \
	 entries (default 50, max 1000). Entries are rendered as compact JSON, one per line.",
	json!({
	    "type": "object",
	    "properties": {
	    "kind": { "type": "string", "description": "Event kind filter" },
	    "turn": { "type": "integer", "description": "Turn number filter" },
	    "tail": { "type": "integer", "description": "Last N entries (default 50, max 1000)" }
	    }
	}),
	move |args: serde_json::Value| {
	    let log_path = log_path.clone();
	    Box::pin(async move {
		let kind = args.get("kind").and_then(|v| v.as_str()).map(String::from);
		let turn = args.get("turn").and_then(|v| v.as_u64());
		let tail = args
		    .get("tail")
		    .and_then(|v| v.as_u64())
		    .unwrap_or(50)
		    .clamp(1, 1000) as usize;

		let content = std::fs::read_to_string(&log_path).map_err(|e| {
		    ToolExecutionError::provider(format!("reading {}: {e}", log_path.display()))
		})?;
		let mut entries: Vec<serde_json::Value> = Vec::new();
		for line in content.lines() {
		    let line = line.trim();
		    if line.is_empty() {
			continue;
		    }
		    let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else {
			continue;
		    };
		    if let Some(k) = &kind
			&& v.get("kind").and_then(|x| x.as_str()) != Some(k.as_str())
		    {
			continue;
		    }
		    if let Some(t) = turn
			&& v.get("turn").and_then(|x| x.as_u64()) != Some(t)
		    {
			continue;
		    }
		    entries.push(v);
		}
		let start = entries.len().saturating_sub(tail);
		let mut rendered = entries[start..]
		    .iter()
		    .map(|v| v.to_string())
		    .collect::<Vec<_>>()
		    .join("\n");
		if rendered.is_empty() {
		    rendered = "no log entries match".to_string();
		}
		Ok(ToolOutput::text(cap_output(&rendered)))
	    })
	},
    )
}

